def closest_integer(value):
    """
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples:
        >>> closest_integer("10")
        10
        >>> closest_integer("15.3")
        15
        >>> closest_integer("14.5")   # rounds away from zero -> 15
        15
        >>> closest_integer("-14.5")  # rounds away from zero -> -15
        -15
    """

    num = float(value)

    if abs(num % 1) < 0.5:
        return int(round(num))
    elif abs(num % 1) > 0.5:
        return round(num)
    else:  # exactly halfway (e.g., x.5 or -x.5)
        if num >= 0:
            return int(num + 0.5)   # rounds up away from zero for positive
        else:
            return int(num - 0.5)   # rounds down away from zero for negative

