import math

def closest_integer(value):
    num = float(value)

    if abs(num % 1) < 0.5:
        return round(num)
    elif abs(num % 1) > 0.5:
        return -math.floor(-num) if num < 0 else math.ceil(num)
    else:  # exactly x.5 or -x.5 → away from zero
        if num >= 0:
            return int(math.ceil(num))
        else:
            return int(math.floor(num))

