def closest_integer(value):
    import math
    n = float(value)

    # Standard rounding (round half to even in Python 3, so we adjust for our rule)
    rounded = int(math.floor(n + 0.5)) if n >= 0 else int(math.ceil(n - 0.5))

    return rounded

